import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Payments — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payments — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/payments"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payments — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/payments"}]]},"headers":[],"relativePath":"user-guide/payments.md","filePath":"user-guide/payments.md","lastUpdated":1786188368000}'),s={name:"user-guide/payments.md"};function r(i,e,l,d,c,m){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="payments-—-user-guide" tabindex="-1">Payments — User Guide <a class="header-anchor" href="#payments-—-user-guide" aria-label="Permalink to &quot;Payments — User Guide&quot;">​</a></h1><h2 id="who-can-use-payments" tabindex="-1">Who can use Payments <a class="header-anchor" href="#who-can-use-payments" aria-label="Permalink to &quot;Who can use Payments&quot;">​</a></h2><p>Your workspace must have <strong>Invoices</strong> installed first, then the <strong>Payments</strong> module (both free from Marketplace). Marketplace blocks installing Payments until Invoices is entitled. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>post</code>, <code>void</code> as needed).</p><p>Without <strong>assign</strong>, you only see payments assigned to you.</p><blockquote><p><strong>Not the same as Central Billing → Payments.</strong> This module tracks money your workspace receives <em>from your own customers</em>. The platform&#39;s own <strong>Central → Billing → Payments</strong> area (in the platform admin, not here) tracks what your workspace pays the platform for its module subscriptions.</p></blockquote><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Payments</strong> from the sidebar (<strong>Billing</strong>, under Invoices). Search by payment number or reference, filter by status or method, toggle <strong>My payments</strong>, and switch KPI cards (My Payments, Draft, Posted, Void, Posted total) to quick-filter the table.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted payment from the row menu</li><li><strong>Delete permanently</strong> requires <code>payments.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="record-a-payment" tabindex="-1">Record a payment <a class="header-anchor" href="#record-a-payment" aria-label="Permalink to &quot;Record a payment&quot;">​</a></h2><ol><li>Click <strong>New payment</strong></li><li>Enter the amount, currency, method (Cash, Bank Transfer, Cheque, Card (manual), Other), date paid, reference, and notes</li><li>Optionally link a contact or company (when Contacts/Companies is installed)</li><li>Add one or more <strong>allocations</strong> — pick an outstanding invoice and the amount of this payment to apply to it. You can allocate to several invoices, or leave it unallocated and add allocations later while still in Draft</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>You can also start recording a payment from an invoice&#39;s detail view — the <strong>Related payments</strong> link jumps you to the Payments module.</p><p>Edit from the row menu or the detail sheet while the payment is still <strong>Draft</strong>. Editing replaces the full allocation list. After <strong>Post</strong>, content is locked; use <strong>Void</strong> and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A payment starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Post</strong> (<code>draft → posted</code>) — applies every allocation to its invoice&#39;s balance: the invoice&#39;s amount paid increases and its status advances (e.g. <code>sent → partial</code> or <code>sent → paid</code>, depending on how much of the invoice is now covered). Posting is all-or-nothing: it&#39;s rejected if any allocated invoice has been deleted, is not currently Sent or Partial, or if the allocated amount would exceed that invoice&#39;s balance due</li><li><strong>Void</strong> (<code>posted → void</code>) — reverses every allocation, rolling the linked invoices&#39; balances and statuses back, even if an invoice has since been fully paid off by another payment or deleted</li></ul><p>Invalid transitions (e.g. voiding a draft payment, or posting an already-posted payment) are rejected with a validation error.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail sheet or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the payment</li><li><strong>Activity</strong> — timeline of create, update, assignment, post, void, note, and delete/restore events</li></ul><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Partial refunds of a posted payment, payment receipt PDFs/e-mail delivery, and online payment-gateway capture are planned but not part of this module yet — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p><p>To credit an invoice directly (independent of a payment), see <a href="/user-guide/credit-notes">Credit Notes</a>.</p>',23)])])}const u=t(s,[["render",r]]);export{h as __pageData,u as default};
